export function LazyLoading({
  belowFoldLoaded = {{belowFoldLoaded}},
  trigger = "{{trigger}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ height: 54, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", color: "#241430", fontWeight: 600, marginBottom: 8, padding: 4, background: accent }}>Image 1 &mdash; loaded eagerly</div>
      <div style={{ textAlign: "center", margin: "4px 0 8px", opacity: .5 }}>below the fold &darr;</div>
      <div style={{ height: 54, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", fontWeight: belowFoldLoaded ? 600 : 400, marginBottom: 8, padding: 4, background: belowFoldLoaded ? accent : "repeating-linear-gradient(45deg, #24143010 0 8px, transparent 8px 16px)", color: belowFoldLoaded ? "#241430" : "#241430aa" }}>
        {belowFoldLoaded ? `Image 2 \u2014 loaded on ${trigger}` : "not requested yet"}
      </div>
      <p style={{ margin: "6px 0 0" }}>Only what's needed loads up front &mdash; the rest waits for {trigger}</p>
    </div>
  );
}
